using namespace std;

class Solution {
public:
    int largestInteger(vector<int>& nums, int k) {
        int n = nums.size();
        if (k == n) {
            return *max_element(nums.begin(), nums.end());
        }
        unordered_map<int, int> count;
        for (int x : nums) count[x]++;

        if (k == 1) {
            int ans = -1;
            for (const auto& [x, freq] : count) {
                if (freq == 1 && x > ans) ans = x;
            }
            return ans;
        }

        int ans = -1;
        if (count[nums.front()] == 1) ans = max(ans, nums.front());
        if (count[nums.back()] == 1) ans = max(ans, nums.back());
        return ans;
    }
};

import java.util.HashMap;
import java.util.Map;

class Solution {
    public int largestInteger(int[] nums, int k) {
        int n = nums.length;
        if (k == n) {
            int mx = nums[0];
            for (int x : nums) mx = Math.max(mx, x);
            return mx;
        }

        Map<Integer, Integer> count = new HashMap<>();
        for (int x : nums) {
            count.put(x, count.getOrDefault(x, 0) + 1);
        }

        if (k == 1) {
            int ans = -1;
            for (Map.Entry<Integer, Integer> entry : count.entrySet()) {
                if (entry.getValue() == 1 && entry.getKey() > ans) {
                    ans = entry.getKey();
                }
            }
            return ans;
        }

        int ans = -1;
        if (count.get(nums[0]) == 1) ans = Math.max(ans, nums[0]);
        if (count.get(nums[n - 1]) == 1) ans = Math.max(ans, nums[n - 1]);
        return ans;
    }
}

